function validate(input) {
  const [{ Sales = [] }] = input;
  const fruits = new Map();
  for (const [date, fruit, sold] of Sales) {
    if (date === null) return 'Every sale needs a sale_date.';
    if (fruit !== 'apples' && fruit !== 'oranges') return `fruit must be 'apples' or 'oranges', not ${fruit}.`;
    if (sold === null || sold < 0) return `sold_num on ${date} must be a non-negative number.`;
    const seen = fruits.get(date) || new Set();
    if (seen.has(fruit)) return `${fruit} appears twice on ${date}.`;
    seen.add(fruit);
    fruits.set(date, seen);
  }
  for (const [date, seen] of fruits) if (seen.size !== 2) return `${date} needs a row for both apples and oranges.`;
  return null;
}

