function generate(rand, size) {
  const small = size === 'small';
  const days = small ? Math.floor(rand() * 5) : 1000;
  const start = Date.UTC(2019, 11, 28);
  const offsets = [];
  for (let k = 0; k < (small ? 12 : 2500); k++) offsets.push(k);
  // Pick distinct days at random so dates have gaps and cross month and year boundaries.
  for (let i = offsets.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [offsets[i], offsets[j]] = [offsets[j], offsets[i]]; }
  const counts = [0, 0, 5, 8, 10, 15, 15, 20];
  const amount = () => (small ? counts[Math.floor(rand() * counts.length)] : Math.floor(rand() * 200));
  const Sales = [];
  for (const k of offsets.slice(0, days)) {
    const date = new Date(start + k * 86400000).toISOString().slice(0, 10);
    Sales.push([date, 'apples', amount()], [date, 'oranges', amount()]);
  }
  for (let i = Sales.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [Sales[i], Sales[j]] = [Sales[j], Sales[i]]; }
  return [{ Sales }];
}
